      hu: ["Szarvasmarha-tartas", "Nagy legelok", "Videki munkakultura"],
      ro: ["Cresterea vitelor", "Pajisti intinse", "Cultura muncii rurale"],
      en: ["Cattle ranching", "Large pastures", "Rural work culture"]
