      hu: ["Vizicsuszda", "Csaladi kirandulas", "Nepszeru a forro nyugaton"],
      ro: ["Tobogane de apa", "Iesire in familie", "Popular in vestul cald"],
      en: ["Water slides", "Family outing", "Popular in the hot west"]
